// AsTypeDeclaration returns a view of n if it is a type_declaration.
func AsTypeDeclaration(n *Node) (TypeDeclarationView, bool) {
	if n == nil || n.Kind != TypeDeclaration {
		return TypeDeclarationView{}, false
	}
	return TypeDeclarationView{n}, true
}

// Name returns the name child (type_identifier).
func (v TypeDeclarationView) Name() *Node { return v.Node.ChildByField(FieldName) }

// TypeParameters returns the type_parameters child (type_parameters), or nil.
func (v TypeDeclarationView) TypeParameters() *Node { return v.Node.ChildByField(FieldTypeParameters) }

// Value returns the value child (_type, variant_list).
func (v TypeDeclarationView) Value() *Node { return v.Node.ChildByField(FieldValue) }

// Items returns the named children that have no field (attribute).
func (v TypeDeclarationView) Items() []*Node { return v.Node.unfielded() }

